/**
 * ⚙️ CONFIGURATION — Set your Google Spreadsheet ID here (from the URL):
 * https://docs.google.com/spreadsheets/d/YOUR_SPREADSHEET_ID/edit
 */
var SPREADSHEET_ID = "1JmoJ395DJ4_fvp4guzoxb4UcxUDLdDwTTBwNmmJIXyU";

/**
 * Safe Sheet Locator (Fixed for Web App deployment)
 * In deployed web apps, getActiveSpreadsheet() always returns null.
 * This function tries multiple methods to find the right sheet.
 */
function getWorkshopSheet() {
  // Method 1: Use hardcoded SPREADSHEET_ID (most reliable for web apps)
  if (SPREADSHEET_ID && SPREADSHEET_ID.length > 10) {
    try {
      var ss = SpreadsheetApp.openById(SPREADSHEET_ID);
      if (ss) return ss.getSheets()[0];
    } catch (e) {
      Logger.log("getWorkshopSheet openById error: " + e.toString());
    }
  }

  // Method 2: Try the bound spreadsheet (works when script is opened inside Sheets)
  try {
    var ss = SpreadsheetApp.getActiveSpreadsheet();
    if (ss) {
      var sheets = ss.getSheets();
      if (sheets && sheets.length > 0) return sheets[0];
    }
  } catch (e) { }

  // Method 3: Search Google Drive by spreadsheet name
  try {
    var files = DriveApp.getFilesByName("Guntur workshop list");
    if (files.hasNext()) {
      return SpreadsheetApp.openById(files.next().getId()).getSheets()[0];
    }
  } catch (e) { }

  // Method 4: Fuzzy Drive search
  try {
    var files = DriveApp.searchFiles('mimeType = "application/vnd.google-apps.spreadsheet" and name contains "Guntur"');
    if (files.hasNext()) {
      return SpreadsheetApp.openById(files.next().getId()).getSheets()[0];
    }
  } catch (e) { }

  Logger.log("CRITICAL: Could not find the workshop spreadsheet. Set SPREADSHEET_ID variable.");
  return null;
}

/**
 * [FUNCTION 1] RUN THIS FUNCTION IN APPS SCRIPT TO GENERATE PASSES FOR ALL EXISTING ROWS:
 */
function generateAllPassPdfs() {
  var testDrive = DriveApp.getRootFolder();
  var sheet = getWorkshopSheet();

  if (!sheet) {
    Logger.log("Error: Could not locate active sheet or 'Guntur workshop list' spreadsheet.");
    try {
      SpreadsheetApp.getUi().alert("Could not locate active sheet or 'Guntur workshop list'. Please open the Google Sheet directly and go to Extensions > Apps Script.");
    } catch (e) { }
    return;
  }

  var pdfCol = ensurePassPdfColumnExists(sheet);
  var lastRow = sheet.getLastRow();
  if (lastRow <= 1) {
    try { SpreadsheetApp.getUi().alert("No participant records found in this sheet."); } catch (e) { }
    return;
  }

  var dataRange = sheet.getRange(1, 1, lastRow, sheet.getLastColumn());
  var allData = dataRange.getValues();
  var allFormulas = dataRange.getFormulas();
  var headers = allData[0];
  var cols = mapHeaderIndices(headers);

  var count = 0;
  for (var r = 1; r < allData.length; r++) {
    var row = allData[r];
    var currentVal = String(row[pdfCol - 1] || '');
    var currentFormula = String(allFormulas[r][pdfCol - 1] || '');

    var hasPdf = (currentVal.indexOf('http') !== -1) ||
      (currentFormula.indexOf('http') !== -1) ||
      (currentVal.indexOf('Download Pass PDF') !== -1);

    if (!hasPdf) {
      var regId = (cols.regId >= 0 && row[cols.regId]) ? String(row[cols.regId]).trim() : ('CCM-GNT-' + (10000 + r));
      var fullName = (cols.fullName >= 0 && row[cols.fullName]) ? String(row[cols.fullName]).trim() : 'Participant';
      var mobile = (cols.mobile >= 0 && row[cols.mobile]) ? String(row[cols.mobile]).trim() : '-';
      var email = (cols.email >= 0 && row[cols.email]) ? String(row[cols.email]).trim() : '-';
      var age = (cols.age >= 0 && row[cols.age]) ? String(row[cols.age]).trim() : '—';
      var category = (cols.category >= 0 && row[cols.category]) ? String(row[cols.category]).trim() : 'Content Creator';
      var knowledge = (cols.knowledge >= 0 && row[cols.knowledge]) ? String(row[cols.knowledge]).trim() : 'Beginner';
      var location = (cols.location >= 0 && row[cols.location]) ? String(row[cols.location]).trim() : 'Guntur';
      var utr = (cols.utr >= 0 && row[cols.utr]) ? String(row[cols.utr]).trim() : 'Payment Completed';
      var status = (cols.status >= 0 && row[cols.status]) ? String(row[cols.status]).trim() : 'Confirmed - Payment Submitted';

      var pdfUrl = generateAndSavePassPdf({
        regId: regId,
        fullName: fullName,
        mobile: mobile,
        email: email,
        age: age,
        category: category,
        knowledge: knowledge,
        location: location,
        status: status,
        utr: utr,
        fee: 'Rs. 2,999 (Lunch & Snacks Included)'
      });

      if (pdfUrl && pdfUrl.indexOf('http') !== -1) {
        var cell = sheet.getRange(r + 1, pdfCol);
        cell.setFormula('=HYPERLINK("' + pdfUrl + '", "📄 Download Pass PDF")');
        count++;
      }
    }
  }

  try {
    SpreadsheetApp.getUi().alert('Success! Generated VIP Delegate Pass PDFs for ' + count + ' registration(s) and added download links to your sheet!');
  } catch (uiErr) {
    Logger.log('Generated PDFs for ' + count + ' participants.');
  }
}

